{
    Console.WriteLine($"Agent '{ex.AgentId}' not found");
}
catch (AgentTimeoutException ex)
{
    Console.WriteLine($"Request timed out after {ex.Timeout}");
}
catch (AgentProtocolException ex)
{
    Console.WriteLine($"Error: {ex.Message}");
}
